create table public.question_set_mappings(set_id uuid primary key references public.question_sets(id),mapping jsonb not null);
create table public.question_version_mappings(set_id uuid not null,version integer not null,mapping jsonb not null,primary key(set_id,version),foreign key(set_id,version) references public.question_versions(set_id,version));
alter table public.library_runs add column response_method text check(response_method in ('none','cards'));
alter table public.library_runs add column parent_lesson_id uuid;
alter table public.library_runs add column assignment_id uuid unique;
alter table public.library_runs add column prepared boolean not null default false;
alter table public.library_responses add column answer_states jsonb;
alter table public.library_responses add column response_source text not null default 'manual' check(response_source in ('manual','scan','legacy-import'));
create table public.library_response_history(run_id uuid not null,student_id uuid not null,revision integer not null,answers jsonb not null,answer_states jsonb not null,status text not null,correct integer not null,source text not null,assessed_at date not null,recorded_at timestamptz not null default now(),primary key(run_id,student_id,revision),foreign key(run_id,student_id) references public.library_responses(run_id,student_id));
create table public.group_lessons(id uuid primary key,owner_id uuid not null references auth.users(id),class_id uuid not null,revision integer not null default 1,status text not null check(status in ('draft','active','closed')),lesson_date date not null,payload jsonb not null,prepare_input jsonb not null,foreign key(class_id,owner_id) references public.classes(id,owner_id));
create table public.group_assignments(id uuid primary key,lesson_id uuid not null references public.group_lessons(id),group_id uuid not null,run_id uuid not null unique references public.library_runs(id),method text not null check(method in ('teacher','board','cards')),status text not null check(status in ('ready','active','completed','stopped')),revision integer not null default 1,unique(lesson_id,group_id));
create unique index group_one_board on public.group_assignments(lesson_id) where method='board';
alter table public.library_runs add foreign key(parent_lesson_id) references public.group_lessons(id);
alter table public.library_runs add foreign key(assignment_id) references public.group_assignments(id) deferrable initially deferred;
create table pn_private.group_board_progress(assignment_id uuid primary key references public.group_assignments(id),revision integer not null default 1,position integer not null default 0,answer jsonb,checked boolean not null default false,feedback jsonb,attempt_history jsonb not null default '[]');
create table pn_private.group_board_receipts(assignment_id uuid not null references public.group_assignments(id),actor_id uuid not null,request_id uuid not null,input jsonb not null,primary key(assignment_id,actor_id,request_id));
create index learning_runs_class on public.library_runs(owner_id,class_id,lesson_date desc,id);
create index learning_lessons_class on public.group_lessons(owner_id,class_id,lesson_date desc,id);
create index learning_assignment_lesson on public.group_assignments(lesson_id);
alter table public.question_set_mappings enable row level security; revoke all on public.question_set_mappings from public,anon,authenticated; grant select on public.question_set_mappings to authenticated; create policy learning_read on public.question_set_mappings for select to authenticated using(coalesce(auth.jwt()->>'is_anonymous','')='false' and (exists(select 1 from public.question_sets q where q.id=set_id)));
alter table public.question_version_mappings enable row level security; revoke all on public.question_version_mappings from public,anon,authenticated; grant select on public.question_version_mappings to authenticated; create policy learning_read on public.question_version_mappings for select to authenticated using(coalesce(auth.jwt()->>'is_anonymous','')='false' and (exists(select 1 from public.question_sets q where q.id=set_id)));
alter table public.library_response_history enable row level security; revoke all on public.library_response_history from public,anon,authenticated; grant select on public.library_response_history to authenticated; create policy learning_read on public.library_response_history for select to authenticated using(coalesce(auth.jwt()->>'is_anonymous','')='false' and (exists(select 1 from public.library_runs r where r.id=run_id)));
alter table public.group_lessons enable row level security; revoke all on public.group_lessons from public,anon,authenticated; grant select on public.group_lessons to authenticated; create policy learning_read on public.group_lessons for select to authenticated using(coalesce(auth.jwt()->>'is_anonymous','')='false' and (owner_id=auth.uid()));
alter table public.group_assignments enable row level security; revoke all on public.group_assignments from public,anon,authenticated; grant select on public.group_assignments to authenticated; create policy learning_read on public.group_assignments for select to authenticated using(coalesce(auth.jwt()->>'is_anonymous','')='false' and (exists(select 1 from public.group_lessons l where l.id=lesson_id)));
alter table pn_private.group_board_progress enable row level security; revoke all on pn_private.group_board_progress from public,anon,authenticated;
alter table pn_private.group_board_receipts enable row level security; revoke all on pn_private.group_board_receipts from public,anon,authenticated;

create function pn_private.valid_competency(m jsonb) returns boolean language sql immutable set search_path='' as $$
 select m='null'::jsonb or (m->>'mappingVersion'='1' and (m->>'topicId',m->>'competencyId') in (('bilangan','bilangan-operasi'),('pecahan','pecahan-representasi'),('pecahan','pecahan-operasi'),('perbandingan','perbandingan-senilai'),('aljabar','aljabar-model'),('grafik','grafik-hubungan')))
$$;
create function pn_private.valid_mapping(m jsonb,d jsonb) returns boolean language sql stable set search_path='' as $$
 select pn_private.matches_sync_schema((select body from pn_private.sync_schemas where id='mapping-v1'),m)
 and pn_private.valid_competency(m->'default') and not exists(select 1 from jsonb_array_elements(m->'overrides') o where not pn_private.valid_competency(o->'mapping') or not exists(select 1 from jsonb_array_elements(d->'items') i where i->'id'=o->'itemId'))
 and (select count(*)=count(distinct o->>'itemId') from jsonb_array_elements(m->'overrides') o)
$$;
create function pn_private.learning_run_dto(r public.library_runs) returns jsonb language sql stable set search_path='' as $$
 select pn_private.library_run_dto(r)||jsonb_build_object('responseMethod',coalesce(r.response_method,case when r.mode='assessment' then 'cards' else 'none' end),'mapping',coalesce((select mapping from public.question_version_mappings where set_id=r.set_id and version=r.version),'{"default":null,"overrides":[]}'::jsonb),'parentLessonId',r.parent_lesson_id,'assignmentId',r.assignment_id)
$$;
create function pn_private.learning_set_dto(s public.question_sets) returns jsonb language sql stable set search_path='' as $$
 select pn_private.library_set_dto(s)||jsonb_build_object('mapping',coalesce((select mapping from public.question_set_mappings where set_id=s.id),'{"default":null,"overrides":[]}'::jsonb))
$$;
create function pn_private.learning_detail(r public.library_runs) returns jsonb language sql stable set search_path='' as $$
 select jsonb_build_object('run',pn_private.learning_run_dto(r),'responses',coalesce((select jsonb_agg(jsonb_build_object('studentId',student_id,'revision',revision,'correct',correct,'status',status,'updatedAt',updated_at,'answerStates',coalesce(answer_states,(select jsonb_agg('answered'::text) from jsonb_array_elements(answers))),'answers',case when answer_states is null then answers else (select jsonb_agg(case when answer_states->>(n-1)::int='answered' then a else 'null'::jsonb end order by n) from jsonb_array_elements(answers) with ordinality t(a,n)) end) order by student_id) from public.library_responses where run_id=r.id),'[]'::jsonb))
$$;
create function pn_private.record_learning_response() returns trigger language plpgsql set search_path='' as $$
begin
 insert into public.library_response_history(run_id,student_id,revision,answers,answer_states,status,correct,source,assessed_at) select new.run_id,new.student_id,new.revision,new.answers,coalesce(new.answer_states,(select jsonb_agg('answered'::text) from jsonb_array_elements(new.answers))),new.status,new.correct,new.response_source,r.lesson_date from public.library_runs r where r.id=new.run_id;
 if exists(select 1 from public.library_runs r join public.group_lessons l on l.id=r.parent_lesson_id where r.id=new.run_id and (l.payload->>'assessmentRevision')::int>0) then
 update public.group_lessons l set revision=l.revision+1,payload=jsonb_set(jsonb_set(l.payload,'{assessmentRevision}',to_jsonb((l.payload->>'assessmentRevision')::int+1)),'{revision}',to_jsonb(l.revision+1)) where l.id=(select parent_lesson_id from public.library_runs where id=new.run_id);
 end if;return new;
end $$;
insert into public.library_response_history(run_id,student_id,revision,answers,answer_states,status,correct,source,assessed_at,recorded_at) select p.run_id,p.student_id,p.revision,p.answers,(select jsonb_agg('answered'::text) from jsonb_array_elements(p.answers)),p.status,p.correct,'legacy-import',r.lesson_date,p.updated_at from public.library_responses p join public.library_runs r on r.id=p.run_id;
create trigger learning_response_history after insert or update on public.library_responses for each row execute function pn_private.record_learning_response();

alter function public.library_action(jsonb,uuid) rename to library_action_before_learning;
revoke all on function public.library_action_before_learning(jsonb,uuid) from public,anon,authenticated;
create function public.library_action(p_input jsonb,p_controller uuid default null) returns jsonb language plpgsql security definer set search_path='' as $$
declare result jsonb;r public.library_runs;m jsonb;s public.question_sets;
begin
 if auth.uid() is null or coalesce(auth.jwt()->>'is_anonymous','')<>'false' then return '{"error":"FORBIDDEN"}';end if;
 if p_input->>'action' not in ('list','save','archive','roster') then
 select * into r from public.library_runs where id=(p_input->>'id')::uuid and owner_id=auth.uid();
 if r.parent_lesson_id is not null or (r.response_method='cards' and r.mode='teach') or exists(select 1 from public.library_responses where run_id=r.id and answer_states is not null and exists(select 1 from jsonb_array_elements_text(answer_states) state where state<>'answered')) then return '{"error":"CONFLICT"}';end if;
 end if;
 result=public.library_action_before_learning(p_input,p_controller);
 if result ? 'error' then return result;end if;
 if p_input->>'action'='list' then
 result=jsonb_set(result,'{runs}',coalesce((select jsonb_agg(x) from jsonb_array_elements(result->'runs') x where not exists(select 1 from public.library_runs rr where rr.id=(x->>'id')::uuid and (rr.parent_lesson_id is not null or (rr.response_method='cards' and rr.mode='teach')))),'[]'));
 elsif p_input->>'action'='save' and (p_input->>'ready')::boolean then
 select mapping into m from public.question_set_mappings where set_id=(p_input->>'id')::uuid;
 if m is not null then insert into public.question_version_mappings values((p_input->>'id')::uuid,(result->>'version')::int,m);end if;
 end if;return result;
exception when invalid_text_representation then return '{"error":"INVALID_INPUT"}';end $$;
grant execute on function public.library_action(jsonb,uuid) to authenticated;revoke all on function public.library_action(jsonb,uuid) from public,anon;
create function public.library_action_v2(p_input jsonb,p_controller uuid default null) returns jsonb language plpgsql security definer set search_path='' as $$
declare a text=p_input->>'action';old_input jsonb=p_input-'contractVersion'-'mapping'-'responseMethod'-'answerStates'-'source';result jsonb;r public.library_runs;s public.question_sets;old public.library_responses;d jsonb;answers jsonb;score int;m jsonb;control jsonb;
begin
 if auth.uid() is null or coalesce(auth.jwt()->>'is_anonymous','')<>'false' then return '{"error":"FORBIDDEN"}';end if;
 if not pn_private.matches_sync_schema((select body from pn_private.sync_schemas where id='library-v2'),p_input) then return '{"error":"INVALID_INPUT"}';end if;
 if a not in ('list','detail') then control=public.sample_control(p_controller,false,false);if control ? 'error' then return control;end if;end if;
 if a='list' then return jsonb_build_object('sample',public.is_sample_teacher(),'collections',coalesce((select jsonb_agg(pn_private.learning_set_dto(q) order by q.source,q.id) from public.question_sets q where q.owner_id=auth.uid() or q.source='system'),'[]'),'runs',coalesce((select jsonb_agg(pn_private.learning_run_dto(q) order by q.lesson_date desc,q.id) from public.library_runs q where q.owner_id=auth.uid() and q.parent_lesson_id is null),'[]'));
 elsif a='save' then
 if not pn_private.valid_mapping(p_input->'mapping',p_input->'document') then return '{"error":"INVALID_INPUT"}';end if;
 result=public.library_action_before_learning(old_input,p_controller);if result ? 'error' then return result;end if;
 insert into public.question_set_mappings values((p_input->>'id')::uuid,p_input->'mapping') on conflict(set_id) do update set mapping=excluded.mapping;
 if (p_input->>'ready')::boolean then insert into public.question_version_mappings values((p_input->>'id')::uuid,(result->>'version')::int,p_input->'mapping');end if;
 select * into s from public.question_sets where id=(p_input->>'id')::uuid;return pn_private.learning_set_dto(s);
 elsif a='archive' or a='roster' then
 result=public.library_action_before_learning(old_input,p_controller);if result ? 'error' or a='roster' then return result;end if;
 select * into s from public.question_sets where id=(p_input->>'id')::uuid;return pn_private.learning_set_dto(s);
 elsif a='start' then
 perform 1 from public.classes where id=(p_input->>'classId')::uuid and owner_id=auth.uid() for update;if not found then return '{"error":"FORBIDDEN"}';end if;
 if p_input->>'mode'='assessment' and p_input->>'responseMethod'<>'cards' then return '{"error":"INVALID_INPUT"}';end if;
 if p_input->>'responseMethod'='cards' and not exists(select 1 from public.question_versions where set_id=(p_input->>'collectionId')::uuid and version=(p_input->>'version')::int and document->>'kind'='cards') then return '{"error":"INVALID_INPUT"}';end if;
 select * into r from public.library_runs where id=(p_input->>'id')::uuid;
 if found and (r.owner_id<>auth.uid() or r.parent_lesson_id is not null or coalesce(r.response_method,case when r.mode='assessment' then 'cards' else 'none' end)<>p_input->>'responseMethod') then return '{"error":"CONFLICT"}';end if;
 result=public.library_action_before_learning(old_input,p_controller);if result ? 'error' then return result;end if;
 update public.library_runs set response_method=p_input->>'responseMethod' where id=(p_input->>'id')::uuid returning * into r;return pn_private.learning_run_dto(r);
 end if;
 -- Class/lesson locks precede child response locks; closure and correction serialize.
 select * into r from public.library_runs where id=(p_input->>'id')::uuid and owner_id=auth.uid();if not found then return '{"error":"NOT_FOUND"}';end if;
 perform 1 from public.classes where id=r.class_id for update;
 if r.parent_lesson_id is not null then perform 1 from public.group_lessons where id=r.parent_lesson_id for update;end if;
 select * into r from public.library_runs where id=r.id for update;
 if a='detail' then return pn_private.learning_detail(r);end if;
 if a in ('position','close') then
 if r.parent_lesson_id is not null then return '{"error":"CONFLICT"}';end if;
 result=public.library_action_before_learning(old_input,p_controller);if result ? 'error' then return result;end if;
 select * into r from public.library_runs where id=r.id;return pn_private.learning_run_dto(r);
 end if;
 if a='response' then
 select document into d from public.question_versions where set_id=r.set_id and version=r.version;
 if r.prepared or coalesce(r.response_method,case when r.mode='assessment' then 'cards' else 'none' end)<>'cards' or r.form_id<>(p_input->>'formId')::uuid or r.version<>(p_input->>'version')::int or not exists(select 1 from jsonb_array_elements(r.roster) st where st->>'id'=p_input->>'studentId') or jsonb_array_length(p_input->'answers')<>jsonb_array_length(d->'items') or jsonb_array_length(p_input->'answerStates')<>jsonb_array_length(d->'items') then return '{"error":"INVALID_INPUT"}';end if;
 if exists(select 1 from jsonb_array_elements(p_input->'answers') with ordinality t(v,n) where ((p_input->'answerStates'->>(n-1)::int='answered')<>(v<>'null'::jsonb))) or (p_input->>'status'='received' and exists(select 1 from jsonb_array_elements_text(p_input->'answerStates') x where x<>'answered')) then return '{"error":"INVALID_INPUT"}';end if;
 select jsonb_agg(case when v='null'::jsonb then '"?"'::jsonb else v end order by n) into answers from jsonb_array_elements(p_input->'answers') with ordinality t(v,n);
 select * into old from public.library_responses where run_id=r.id and student_id=(p_input->>'studentId')::uuid;
 if found and old.answers=answers and old.status=p_input->>'status' and coalesce(old.answer_states,(select jsonb_agg('answered'::text) from jsonb_array_elements(old.answers)))=p_input->'answerStates' then return pn_private.learning_detail(r);end if;
 if coalesce(old.revision,0)<>(p_input->>'revision')::int then return '{"error":"CONFLICT"}';end if;
 select count(*) into score from jsonb_array_elements(d->'items') with ordinality t(q,n) where q->>'key'=answers->>(n-1)::int and p_input->'answerStates'->>(n-1)::int='answered';
 insert into public.library_responses(run_id,student_id,answers,correct,status,answer_states,response_source) values(r.id,(p_input->>'studentId')::uuid,answers,score,p_input->>'status',p_input->'answerStates',p_input->>'source') on conflict(run_id,student_id) do update set answers=excluded.answers,correct=excluded.correct,status=excluded.status,answer_states=excluded.answer_states,response_source=excluded.response_source,revision=library_responses.revision+1,updated_at=now();
 return pn_private.learning_detail(r);
 end if;return '{"error":"INVALID_INPUT"}';
exception when unique_violation then return '{"error":"CONFLICT"}';when invalid_text_representation or datetime_field_overflow then return '{"error":"INVALID_INPUT"}';end $$;
revoke all on function public.library_action_v2(jsonb,uuid) from public,anon;grant execute on function public.library_action_v2(jsonb,uuid) to authenticated;

create function pn_private.lesson_dto(l public.group_lessons) returns jsonb language sql stable set search_path='' as $$
 select l.payload||jsonb_build_object('revision',l.revision,'status',l.status,'assignments',coalesce((select jsonb_agg(jsonb_build_object('id',a.id,'groupId',a.group_id,'method',a.method,'collectionId',r.set_id,'version',r.version,'runId',r.id,'formId',r.form_id,'roster',r.roster,'status',a.status,'revision',a.revision) order by a.group_id) from public.group_assignments a join public.library_runs r on r.id=a.run_id where a.lesson_id=l.id),'[]'))
$$;
create function pn_private.topic_evidence(cid uuid,presence jsonb,competency jsonb) returns jsonb language sql stable set search_path='' as $$
 with forms as (
 select r.id,r.set_id,r.version,r.lesson_date,v.document,m.mapping,
 (select jsonb_agg(i->'id' order by n) from jsonb_array_elements(v.document->'items') with ordinality t(i,n) where i->>'kind'='card' and coalesce((select o->'mapping' from jsonb_array_elements(m.mapping->'overrides') o where o->'itemId'=i->'id'),m.mapping->'default')->>'competencyId'=competency->>'competencyId') item_ids
 from public.library_runs r join public.question_versions v on v.set_id=r.set_id and v.version=r.version join public.question_version_mappings m on m.set_id=r.set_id and m.version=r.version where r.class_id=cid and r.owner_id=auth.uid() and not r.synthetic and not r.prepared and coalesce(r.response_method,case when r.mode='assessment' then 'cards' else 'none' end)='cards'),
 observations as (
 select f.*,p.student_id,p.revision response_revision,
 'same-form-topic-v1:'||f.set_id::text||':'||f.version||':'||(competency->>'competencyId')||':'||(select string_agg(id,',' order by n) from jsonb_array_elements_text(f.item_ids) with ordinality t(id,n)) comparison_key,
 (select count(*) from jsonb_array_elements(f.document->'items') with ordinality t(q,n) where f.item_ids @> jsonb_build_array(q->'id') and q->>'key'=p.answers->>(n-1)::int) correct
 from forms f join public.library_responses p on p.run_id=f.id where f.item_ids is not null and p.status='received' and not exists(select 1 from jsonb_array_elements_text(coalesce(p.answer_states,'[]')) x where x<>'answered') and exists(select 1 from jsonb_array_elements(presence) s where s->>'id'=p.student_id::text)),
 cohort as (select comparison_key from observations group by comparison_key order by count(distinct student_id) desc,max(lesson_date) desc,comparison_key limit 1),
 chosen as (select distinct on (student_id) o.* from observations o join cohort c using(comparison_key) order by student_id,lesson_date desc,id desc)
 select coalesce(jsonb_agg(jsonb_build_object('studentId',s->'id','status',case when e.id is null then 'unknown' else 'known' end,'reason',case when e.id is not null then 'comparable' when competency='null' then 'unmapped' when exists(select 1 from observations o where o.student_id::text=s->>'id') then 'not_comparable' else 'no_result' end,'evidence',case when e.id is null then null else jsonb_build_object('source','library_cards','runId',e.id,'collectionId',e.set_id,'version',e.version,'responseRevision',e.response_revision,'assessedAt',e.lesson_date,'competencyId',competency->>'competencyId','comparisonKey',e.comparison_key,'itemIds',e.item_ids,'correct',e.correct,'total',jsonb_array_length(e.item_ids)) end) order by s->>'attendanceNumber'),'[]') from jsonb_array_elements(presence) s left join chosen e on e.student_id::text=s->>'id'
$$;
create function pn_private.suggest_groups(presence jsonb,evidence jsonb,n integer,seed text,source text) returns jsonb language plpgsql immutable set search_path='' as $$
declare groups jsonb='[]';members jsonb;known jsonb;unknowns jsonb;p jsonb;i int=0;idx int;smallest int;g uuid;
begin
 if n<1 or n>jsonb_array_length(presence) then raise exception 'invalid group count';end if;
 for i in 0..n-1 loop g=(substr(md5(seed||':'||i),1,8)||'-'||substr(md5(seed||':'||i),9,4)||'-4'||substr(md5(seed||':'||i),14,3)||'-8'||substr(md5(seed||':'||i),18,3)||'-'||substr(md5(seed||':'||i),21,12))::uuid;groups=groups||jsonb_build_array(jsonb_build_object('id',g,'label','Kelompok '||(i+1),'studentIds','[]'::jsonb));end loop;
 select coalesce(jsonb_agg(member order by (e->'evidence'->>'correct')::numeric/(e->'evidence'->>'total')::int,md5(seed||(member->>'id'))),'[]') into known from jsonb_array_elements(presence) member join jsonb_array_elements(evidence) e on e->'studentId'=member->'id' where source='evidence' and e->>'status'='known';
 i=0;for p in select value from jsonb_array_elements(known) loop idx=least(n-1,floor(i::numeric*n/jsonb_array_length(known))::int);members=groups->idx->'studentIds';groups=jsonb_set(groups,array[idx::text,'studentIds'],members||jsonb_build_array(p->'id'));i=i+1;end loop;
 for p in select x from jsonb_array_elements(presence) x where not exists(select 1 from jsonb_array_elements(known) k where k->'id'=x->'id') order by md5(seed||(x->>'id')) loop
 select ordinality-1 into idx from jsonb_array_elements(groups) with ordinality t(x,ordinality) order by jsonb_array_length(x->'studentIds'),md5(seed||(p->>'id')||ordinality) limit 1;
 groups=jsonb_set(groups,array[idx::text,'studentIds'],groups->idx->'studentIds'||jsonb_build_array(p->'id'));
 end loop;
 for i in 0..n-1 loop if jsonb_array_length(groups->i->'studentIds')=0 then
 select ordinality-1 into idx from jsonb_array_elements(groups) with ordinality t(x,ordinality) order by jsonb_array_length(x->'studentIds') desc limit 1;
 members=groups->idx->'studentIds';groups=jsonb_set(groups,array[i::text,'studentIds'],jsonb_build_array(members->(jsonb_array_length(members)-1)));groups=jsonb_set(groups,array[idx::text,'studentIds'],members-(jsonb_array_length(members)-1));
 end if;end loop;return groups;
end $$;
create function pn_private.valid_lesson_groups(presence jsonb,groups jsonb) returns boolean language sql immutable set search_path='' as $$
 select jsonb_array_length(groups)>0 and not exists(select 1 from jsonb_array_elements(groups) g where jsonb_array_length(g->'studentIds')=0)
 and (select count(*)=count(distinct g->>'id') from jsonb_array_elements(groups) g)
 and (select count(*)=jsonb_array_length(presence) and count(*)=count(distinct id) from jsonb_array_elements(groups) g,jsonb_array_elements_text(g->'studentIds') id)
 and not exists(select 1 from jsonb_array_elements(groups) g,jsonb_array_elements_text(g->'studentIds') id where not exists(select 1 from jsonb_array_elements(presence) p where p->>'id'=id))
$$;
create function public.group_lesson_action(p_input jsonb,p_controller uuid default null) returns jsonb language plpgsql security definer set search_path='' as $$
declare u uuid=auth.uid();action text=p_input->>'action';l public.group_lessons;c public.classes;r public.library_runs;a public.group_assignments;s public.question_sets;v public.question_versions;presence jsonb;evidence jsonb;groups jsonb;g jsonb;ai jsonb;roster jsonb;control jsonb;runid uuid;oldinput jsonb;missing int;
begin
 if u is null or coalesce(auth.jwt()->>'is_anonymous','')<>'false' then return '{"error":"FORBIDDEN"}';end if;
 if not pn_private.matches_sync_schema((select body from pn_private.sync_schemas where id='group-action-v1'),p_input) or octet_length(p_input::text)>32768 then return '{"error":"INVALID_INPUT"}';end if;
 if action not in ('list','detail') then control=public.sample_control(p_controller,false,false);if control ? 'error' then return control;end if;end if;
 if action='list' then return jsonb_build_object('lessons',coalesce((select jsonb_agg(pn_private.lesson_dto(x) order by x.lesson_date desc,x.id) from public.group_lessons x where x.owner_id=u),'[]'));end if;
 if action='prepare' then
 select * into c from public.classes where id=(p_input->>'classId')::uuid and owner_id=u for update;if not found then return '{"error":"FORBIDDEN"}';end if;
 select * into l from public.group_lessons where id=(p_input->>'id')::uuid;
 if found then if l.owner_id=u and l.prepare_input=p_input then return pn_private.lesson_dto(l);else return '{"error":"CONFLICT"}';end if;end if;
 if not pn_private.valid_competency(p_input->'competency') or exists(select 1 from jsonb_array_elements_text(p_input->'absentStudentIds') absent(id) where not exists(select 1 from public.students where class_id=c.id and active and students.id::text=absent.id)) or (select count(*)<>count(distinct id) from jsonb_array_elements_text(p_input->'absentStudentIds') id) then return '{"error":"INVALID_INPUT"}';end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',id,'attendanceNumber',attendance_number) order by attendance_number),'[]') into presence from public.students where class_id=c.id and active and not p_input->'absentStudentIds' @> jsonb_build_array(id::text);
 if jsonb_array_length(presence)=0 or (p_input->>'groupCount')::int>jsonb_array_length(presence) then return '{"error":"INVALID_INPUT"}';end if;
 evidence=pn_private.topic_evidence(c.id,presence,p_input->'competency');groups=pn_private.suggest_groups(presence,evidence,(p_input->>'groupCount')::int,p_input->>'seed',p_input->>'source');
 insert into public.group_lessons(id,owner_id,class_id,status,lesson_date,prepare_input,payload) values((p_input->>'id')::uuid,u,c.id,'draft',(p_input->>'date')::date,p_input,jsonb_build_object('schemaVersion',1,'id',p_input->'id','classId',c.id,'classLabel',c.label,'date',p_input->'date','revision',1,'status','draft','synthetic',c.runtime_mode='demo','competency',p_input->'competency','seed',p_input->'seed','groupingSource',p_input->'source','presence',presence,'absentStudentIds',p_input->'absentStudentIds','evidenceSnapshot',evidence,'groups',groups,'assignments','[]'::jsonb,'assessmentRevision',0)) returning * into l;return pn_private.lesson_dto(l);
 end if;
 select * into l from public.group_lessons where id=(p_input->>'id')::uuid and owner_id=u;if not found then return '{"error":"NOT_FOUND"}';end if;
 perform 1 from public.classes where id=l.class_id for update;
 select * into l from public.group_lessons where id=l.id for update;
 if action='detail' then return pn_private.lesson_dto(l);end if;
 if action='board-action' then return public.group_board_action(p_input->'input',l.id);end if;
 if action='complete-assignment' then
 if l.status<>'active' then return '{"error":"CONFLICT"}';end if;
 select * into a from public.group_assignments where id=(p_input->>'assignmentId')::uuid and lesson_id=l.id for update;
 if not found or a.method='board' or a.status<>'active' or a.revision<>(p_input->>'assignmentRevision')::int then return '{"error":"CONFLICT"}';end if;
 update public.group_assignments set status='completed',revision=revision+1 where id=a.id;return pn_private.lesson_dto(l);end if;
 if l.revision<>(p_input->>'revision')::int then return '{"error":"CONFLICT"}';end if;
 if action='save' then
 if l.status<>'draft' or not pn_private.valid_lesson_groups(l.payload->'presence',p_input->'groups') or jsonb_array_length(p_input->'assignments')<>jsonb_array_length(p_input->'groups') or (select count(*)<>count(distinct x->>'groupId') or count(*)<>count(distinct x->>'id') from jsonb_array_elements(p_input->'assignments') x) or (select count(*)>1 from jsonb_array_elements(p_input->'assignments') x where x->>'method'='board') then return '{"error":"INVALID_INPUT"}';end if;
 -- Validate every replacement before mutating stored bindings.
 for ai in select value from jsonb_array_elements(p_input->'assignments') loop
 if not exists(select 1 from jsonb_array_elements(p_input->'groups') x where x->'id'=ai->'groupId') then return '{"error":"INVALID_INPUT"}';end if;
 select * into s from public.question_sets where id=(ai->>'collectionId')::uuid and status='ready' and (owner_id=u or source='system');
 select * into v from public.question_versions where set_id=s.id and version=(ai->>'version')::int;
 if s.id is null or v.set_id is null or (ai->>'method'='cards' and v.document->>'kind'<>'cards') then return '{"error":"INVALID_INPUT"}';end if;
 if exists(select 1 from public.group_assignments where id=(ai->>'id')::uuid and lesson_id<>l.id) then return '{"error":"CONFLICT"}';end if;
 end loop;
 -- Keep unchanged snapshots exactly. Changed assignments require a new ID/form.
 for a in select * from public.group_assignments where lesson_id=l.id loop
 select value into ai from jsonb_array_elements(p_input->'assignments') x where x->>'id'=a.id::text;
 if found then
 select * into r from public.library_runs where id=a.run_id;
 select value into g from jsonb_array_elements(p_input->'groups') x where x->'id'=ai->'groupId';
 select jsonb_agg(member order by (member->>'attendanceNumber')::int) into roster from jsonb_array_elements(l.payload->'presence') member where g->'studentIds' @> jsonb_build_array(member->'id');
 if a.group_id::text<>ai->>'groupId' or a.method<>ai->>'method' or r.set_id::text<>ai->>'collectionId' or r.version<>(ai->>'version')::int or r.roster<>roster then return '{"error":"CONFLICT"}';end if;
 end if;end loop;
 -- Removed draft bindings are retained closed; old printed forms cannot grade.
 update public.library_runs set status='closed',prepared=true where id in(select run_id from public.group_assignments where lesson_id=l.id and not exists(select 1 from jsonb_array_elements(p_input->'assignments') x where x->>'id'=group_assignments.id::text));
 delete from pn_private.group_board_progress where assignment_id in(select id from public.group_assignments where lesson_id=l.id and not exists(select 1 from jsonb_array_elements(p_input->'assignments') x where x->>'id'=group_assignments.id::text));
 update public.library_runs set assignment_id=null where parent_lesson_id=l.id and prepared and status='closed';
 delete from public.group_assignments where lesson_id=l.id and not exists(select 1 from jsonb_array_elements(p_input->'assignments') x where x->>'id'=group_assignments.id::text);
 for ai in select value from jsonb_array_elements(p_input->'assignments') loop
 if exists(select 1 from public.group_assignments where id=(ai->>'id')::uuid) then continue;end if;
 select value into g from jsonb_array_elements(p_input->'groups') x where x->'id'=ai->'groupId';
 select jsonb_agg(member order by (member->>'attendanceNumber')::int) into roster from jsonb_array_elements(l.payload->'presence') member where g->'studentIds' @> jsonb_build_array(member->'id');
 runid=gen_random_uuid();
 insert into public.library_runs(id,owner_id,class_id,class_label,set_id,version,lesson_date,mode,roster,synthetic,response_method,parent_lesson_id,assignment_id,prepared) values(runid,u,l.class_id,l.payload->>'classLabel',(ai->>'collectionId')::uuid,(ai->>'version')::int,l.lesson_date,'teach',roster,(l.payload->>'synthetic')::boolean,case when ai->>'method'='cards' then 'cards' else 'none' end,l.id,(ai->>'id')::uuid,true);
 insert into public.group_assignments(id,lesson_id,group_id,run_id,method,status) values((ai->>'id')::uuid,l.id,(ai->>'groupId')::uuid,runid,ai->>'method','ready');
 if ai->>'method'='board' then insert into pn_private.group_board_progress(assignment_id) values((ai->>'id')::uuid);end if;
 end loop;
 update public.group_lessons set revision=revision+1,payload=payload||jsonb_build_object('groups',p_input->'groups','seed',p_input->'seed','groupingSource',p_input->'groupingSource') where id=l.id returning * into l;
 elsif action='begin' then
 if l.status<>'draft' or not exists(select 1 from public.group_assignments where lesson_id=l.id) then return '{"error":"CONFLICT"}';end if;
 if exists(select 1 from public.group_assignments ass join public.library_runs rr on rr.id=ass.run_id join public.question_sets qs on qs.id=rr.set_id where ass.lesson_id=l.id and (qs.status<>'ready' or qs.current_version<>rr.version)) or exists(select 1 from jsonb_array_elements(l.payload->'presence') p where not exists(select 1 from public.students student where student.id::text=p->>'id' and student.class_id=l.class_id and student.active and student.attendance_number=(p->>'attendanceNumber')::int)) or exists(select 1 from public.students student where student.class_id=l.class_id and student.active and not l.payload->'absentStudentIds' @> jsonb_build_array(student.id::text) and not exists(select 1 from jsonb_array_elements(l.payload->'presence') member where member->>'id'=student.id::text)) then return '{"error":"CONFLICT"}';end if;
 update public.library_runs set prepared=false where id in(select run_id from public.group_assignments where lesson_id=l.id);
 update public.group_assignments set status='active',revision=revision+1 where lesson_id=l.id;
 update public.group_lessons set status='active',revision=revision+1 where id=l.id returning * into l;
 elsif action='close' then
 if l.status<>'active' then return '{"error":"CONFLICT"}';end if;
 perform 1 from public.library_runs where parent_lesson_id=l.id order by id for update;
 update public.library_runs set status='closed',revision=revision+1 where parent_lesson_id=l.id and status='active';
 update pn_private.presentations set revoked=true,channel_epoch=gen_random_uuid() where session_id in(select id from public.library_runs where parent_lesson_id=l.id);
 update public.group_assignments set status='stopped',revision=revision+1 where lesson_id=l.id and status='active';
 update public.group_lessons set status='closed',revision=revision+1 where id=l.id returning * into l;
 elsif action='finalize' then
 if l.status<>'closed' then return '{"error":"CONFLICT"}';end if;
 select count(*) into missing from public.group_assignments ass join public.library_runs rr on rr.id=ass.run_id,jsonb_array_elements(rr.roster) p where ass.lesson_id=l.id and ass.method='cards' and not exists(select 1 from public.library_responses x where x.run_id=rr.id and x.student_id::text=p->>'id' and x.status='received');
 if missing>0 and not (p_input->>'acknowledgeMissing')::boolean then return '{"error":"INVALID_INPUT"}';end if;
 update public.group_lessons set revision=revision+1,payload=jsonb_set(payload,'{assessmentRevision}',to_jsonb(greatest(1,(payload->>'assessmentRevision')::int))) where id=l.id returning * into l;
 else return '{"error":"INVALID_INPUT"}';end if;return pn_private.lesson_dto(l);
exception when unique_violation then return '{"error":"CONFLICT"}';when invalid_text_representation or datetime_field_overflow then return '{"error":"INVALID_INPUT"}';end $$;
revoke all on function public.group_lesson_action(jsonb,uuid) from public,anon;grant execute on function public.group_lesson_action(jsonb,uuid) to authenticated;

create function pn_private.rational_value(v jsonb) returns numeric language sql immutable set search_path='' as $$select (v->>'numerator')::numeric/nullif((v->>'denominator')::numeric,0)$$;
create function pn_private.rational_equal(a jsonb,b jsonb) returns boolean language sql immutable set search_path='' as $$select (a->>'numerator')::numeric*(b->>'denominator')::numeric=(b->>'numerator')::numeric*(a->>'denominator')::numeric$$;
create function pn_private.rational_operate(a jsonb,b jsonb,operation text) returns jsonb language sql immutable set search_path='' as $$
 select jsonb_build_object('numerator',case when operation='add' then (a->>'numerator')::numeric*(b->>'denominator')::numeric+(b->>'numerator')::numeric*(a->>'denominator')::numeric when operation='multiply' then (a->>'numerator')::numeric*(b->>'numerator')::numeric else (a->>'numerator')::numeric*(b->>'denominator')::numeric end,'denominator',case when operation='add' then (a->>'denominator')::numeric*(b->>'denominator')::numeric when operation='multiply' then (a->>'denominator')::numeric*(b->>'denominator')::numeric else (a->>'denominator')::numeric*(b->>'numerator')::numeric end)
$$;
create function pn_private.tool_matches(task jsonb,model jsonb) returns boolean language plpgsql immutable set search_path='' as $$
declare prevframe jsonb;expected jsonb;side text;term text;s jsonb=model->'state';f jsonb;bar jsonb;vals numeric[]='{}';x numeric;y numeric;prev numeric;delta numeric;col jsonb;g jsonb;tiles jsonb;leftx numeric;leftc numeric;rightx numeric;rightc numeric;origx numeric;origc numeric;frame jsonb;op jsonb;factor numeric;ml jsonb;t jsonb;q jsonb;pointok boolean=false;
begin
 if task->>'kind'<>model->>'kind' then return false;end if;
 if task->>'kind'='number-line' then
 x=pn_private.rational_value(task->'origin');delta=pn_private.rational_value(task->'delta');prev=x;
 if pn_private.rational_value(s->'origin')<>x or pn_private.rational_value(s->'current')<>x+delta or jsonb_array_length(s->'jumps')=0 then return false;end if;
 for col in select value from jsonb_array_elements(s->'jumps') loop y=pn_private.rational_value(col->'to');if pn_private.rational_value(col->'from')<>prev or (y-prev)*delta<=0 then return false;end if;prev=y;end loop;return prev=x+delta;
 elsif task->>'kind'='ratio' then
 for col in select value from jsonb_array_elements(s->'columns') loop factor=pn_private.rational_value(col->'multiplier');if pn_private.rational_value(col->'x')<>(task->>'baseX')::numeric*factor or pn_private.rational_value(col->'y')<>(task->>'baseY')::numeric*factor then return false;end if;end loop;
 return exists(select 1 from jsonb_array_elements(s->'columns') with ordinality t(c,n) where n>1 and pn_private.rational_value(c->'x')=(task->>'targetX')::numeric);
 elsif task->>'kind'='algebra' then
 if jsonb_array_length(s->'groups')<>(task->>'groups')::int then return false;end if;
 for g in select value from jsonb_array_elements(s->'groups') loop
 select coalesce(sum((v->>'sign')::int) filter(where v->>'kind'='x'),0),coalesce(sum((v->>'sign')::int) filter(where v->>'kind'='unit'),0) into x,y from jsonb_array_elements(g->'tiles') v;
 if x<>(task->>'xPerGroup')::int or y<>(task->>'constantPerGroup')::int then return false;end if;end loop;return true;
 elsif task->>'kind'='fractions' then
 for bar in select value from jsonb_array_elements(s->'bars') loop
 if (select count(*)<>count(distinct v) from jsonb_array_elements(bar->'selected') v) or exists(select 1 from jsonb_array_elements_text(bar->'selected') v where v::int>=(bar->>'parts')::int*(case when jsonb_array_length(to_jsonb(vals))=2 then 2 else 1 end)) then return false;end if;
 vals=array_append(vals,(bar->>'sign')::numeric*jsonb_array_length(bar->'selected')/(bar->>'parts')::numeric);
 end loop;
 x=(task->'left'->>'numerator')::numeric/(task->'left'->>'denominator')::numeric;y=(task->'right'->>'numerator')::numeric/(task->'right'->>'denominator')::numeric;
 if task->>'operation'='equivalent' then return vals[1]=x and vals[1]=vals[2] and s#>>'{bars,0,parts}'<>s#>>'{bars,1,parts}';end if;
 return vals[1]=x and (task->>'operation'='represent' or (vals[2]=y and vals[3]=x+y and s#>>'{bars,0,parts}'=s#>>'{bars,1,parts}' and s#>>'{bars,0,parts}'=s#>>'{bars,2,parts}'));
 elsif task->>'kind'='balance' then
 if jsonb_array_length(s->'history') not between 1 and 60 then return false;end if;
 leftx=(task->'left'->>'x')::numeric;leftc=(task->'left'->>'constant')::numeric;rightx=(task->'right'->>'x')::numeric;rightc=(task->'right'->>'constant')::numeric;
 frame=s->'history'->0;
 if pn_private.rational_value(frame#>'{left,x}')<>leftx or pn_private.rational_value(frame#>'{left,constant}')<>leftc or pn_private.rational_value(frame#>'{right,x}')<>rightx or pn_private.rational_value(frame#>'{right,constant}')<>rightc then return false;end if;
 prevframe=frame;
 for frame in select v from jsonb_array_elements((s->'history')||(jsonb_build_array(s->'frame'))) with ordinality t(v,n) where n>1 loop
 op=frame->'operation';factor=pn_private.rational_value(op->'value');
 if op->>'kind' not in ('add','multiply','divide') or (op->>'kind'<>'add' and factor=0) then return false;end if;
 for side in select unnest(array['left','right']) loop
 for term in select unnest(array['x','constant']) loop
 expected=prevframe->side->term;
 if op->>'kind'<>'add' or op->>'term'=term then expected=pn_private.rational_operate(expected,op->'value',op->>'kind');end if;
 if not pn_private.rational_equal(expected,frame->side->term) then return false;end if;
 end loop;end loop;
 prevframe=frame;leftx=pn_private.rational_value(frame#>'{left,x}');leftc=pn_private.rational_value(frame#>'{left,constant}');rightx=pn_private.rational_value(frame#>'{right,x}');rightc=pn_private.rational_value(frame#>'{right,constant}');
 end loop;return (leftx=1 and leftc=0 and rightx=0) or (rightx=1 and rightc=0 and leftx=0);
 elsif task->>'kind'='graphs' then
 f=s->'frame';ml=f->'model';if jsonb_array_length(s->'history')=0 or ml<>task-'kind'-'domain'-'goal' then return false;end if;
 if task->>'mode'='quadratic' then return (f->>'rootsShown')::boolean;end if;
 x=pn_private.rational_value(f#>'{point,x}');y=pn_private.rational_value(f#>'{point,y}');
 if task->>'mode'='linear' and task#>>'{goal,type}'='intersection' then
 t=task->'lines'->0;q=task->'lines'->1;
 if t->'m'=q->'m' then return f->>'relationship'=case when t->'b'=q->'b' then 'coincident' else 'parallel' end;end if;
 if f->>'relationship'<>'unique' then return false;end if;end if;
 if not (f->>'placed')::boolean or x<(task#>>'{domain,minX}')::numeric or x>(task#>>'{domain,maxX}')::numeric or y<(task#>>'{domain,minY}')::numeric or y>(task#>>'{domain,maxY}')::numeric then return false;end if;
 if task->>'mode'='linear' then
 t=task->'lines'->0;if y<>(t->>'m')::numeric*x+(t->>'b')::numeric then return false;end if;
 if task#>>'{goal,type}'='value' then return x=(task#>>'{goal,x}')::numeric;end if;
 return y=(q->>'m')::numeric*x+(q->>'b')::numeric;
 elsif task->>'mode'='inequalities' then
 for q in select value from jsonb_array_elements(task->'constraints') loop delta=(q->>'a')::numeric*x+(q->>'b')::numeric*y;factor=(q->>'c')::numeric;
 if (q->>'operator'='le' and delta>factor) or (q->>'operator'='lt' and delta>=factor) or (q->>'operator'='ge' and delta<factor) or (q->>'operator'='gt' and delta<=factor) then return false;end if;end loop;return (f->>'shaded')::boolean;
 elsif task->>'mode'='exponential' then
 if trunc(x)<>x then return false;end if;
 delta=pn_private.rational_value(task->'scale')*power(pn_private.rational_value(task->'base'),x+(task->>'shift')::numeric);
 if y<>delta then return false;end if;
 if task#>>'{goal,type}'='value' then return x=(task#>>'{goal,x}')::numeric;end if;return y=pn_private.rational_value(task#>'{goal,y}');
 end if;
 end if;return false;
exception when division_by_zero or numeric_value_out_of_range or invalid_text_representation then return false;end $$;
create function pn_private.group_board_dto(a public.group_assignments) returns jsonb language sql stable set search_path='' as $$
 with data as(select r.id,r.set_id,r.version,p.*,v.document,l.payload from public.library_runs r join pn_private.group_board_progress p on p.assignment_id=a.id join public.question_versions v on v.set_id=r.set_id and v.version=r.version join public.group_lessons l on l.id=a.lesson_id where r.id=a.run_id),
 item as(select *,document->'items'->position q from data)
 select jsonb_build_object('assignmentId',a.id,'runId',a.run_id,'groupLabel',(select g->>'label' from jsonb_array_elements(payload->'groups') g where g->>'id'=a.group_id::text),'title',document->'title','position',position,'total',jsonb_array_length(document->'items'),'revision',revision,'taskEpoch',q->'id','status',a.status,'item',case when q->>'kind'='card' then q-'key'-'explanation' else q end,'answer',answer,'checked',checked,'feedback',feedback,'canNext',checked and a.status='active') from item
$$;
create function public.group_board_action(p_input jsonb,p_teacher_lesson uuid default null) returns jsonb language plpgsql security definer set search_path='' as $$
declare control jsonb;u uuid=auth.uid();board boolean=coalesce(auth.jwt()->>'is_anonymous','')='true';a public.group_assignments;l public.group_lessons;r public.library_runs;p pn_private.presentations;progress pn_private.group_board_progress;old jsonb;q jsonb;d jsonb;passed boolean;action text=p_input->>'action';hist jsonb;
begin
 if u is null or coalesce(auth.jwt()->>'is_anonymous','') not in ('true','false') or not pn_private.matches_sync_schema((select body from pn_private.sync_schemas where id='group-board-v1'),p_input) or octet_length(p_input::text)>131072 then return '{"error":"FORBIDDEN"}';end if;
 select * into p from pn_private.presentations where id=(p_input->>'presentationId')::uuid and not revoked and expires_at>now() and ((board and board_id=u) or (not board and owner_id=u));
 if not found then return '{"error":"FORBIDDEN"}';end if;
 select aa.* into a from public.group_assignments aa join public.library_runs rr on rr.id=aa.run_id where rr.id=p.session_id and aa.method='board';
 if not found then return 'null';end if;
 select * into l from public.group_lessons where id=a.lesson_id;
 if l.status<>'active' or (not board and (p_teacher_lesson is distinct from l.id or l.owner_id<>u)) then return '{"error":"FORBIDDEN"}';end if;
 if action='state' then return pn_private.group_board_dto(a);end if;
 if not board then control=public.sample_control(null,false,false);if control ? 'error' then return control;end if;end if;
 if a.id<>(p_input->>'assignmentId')::uuid or p.channel_epoch<>(p_input->>'channelEpoch')::uuid then return '{"error":"FORBIDDEN"}';end if;
 perform 1 from public.classes where id=l.class_id for update;
 select * into l from public.group_lessons where id=l.id for update;
 select * into r from public.library_runs where id=a.run_id for update;
 select * into p from pn_private.presentations where id=p.id for update;
 select * into a from public.group_assignments where id=a.id for update;
 select * into progress from pn_private.group_board_progress where assignment_id=a.id for update;
 if l.status<>'active' or r.prepared or p.revoked or p.expires_at<=now() or (board and p.board_id<>u) or (not board and p.owner_id<>u) or p.channel_epoch<>(p_input->>'channelEpoch')::uuid then return '{"error":"FORBIDDEN"}';end if;
 select input into old from pn_private.group_board_receipts where assignment_id=a.id and actor_id=u and request_id=(p_input->>'requestId')::uuid;
 if found then if old<>p_input then return '{"error":"CONFLICT"}';end if;return pn_private.group_board_dto(a);end if;
 if a.status<>'active' or progress.revision<>(p_input->>'revision')::int then return '{"error":"CONFLICT"}';end if;
 select document into d from public.question_versions where set_id=r.set_id and version=r.version;q=d->'items'->progress.position;
 if q->>'id'<>p_input->>'taskEpoch' then return '{"error":"CONFLICT"}';end if;
 if not pn_private.consume_pairing_limit('group-board:'||u::text,120) then return '{"error":"RATE_LIMITED"}';end if;
 if action='answer' then
 if p_input#>>'{answer,kind}'<>q->>'kind' or (q->>'kind'='interactive' and p_input#>>'{answer,model,kind}'<>q#>>'{tool,kind}') then return '{"error":"INVALID_INPUT"}';end if;
 update pn_private.group_board_progress set answer=p_input->'answer',checked=false,feedback=null,revision=revision+1 where assignment_id=a.id;
 elsif action='check' then
 if progress.answer is null then return '{"error":"INVALID_INPUT"}';end if;
 passed=case when q->>'kind'='card' then q->>'key'=progress.answer->>'choice' when q->>'kind'='interactive' then pn_private.tool_matches(q->'tool',progress.answer->'model') else false end;
 hist=progress.attempt_history||jsonb_build_array(jsonb_build_object('taskEpoch',q->'id','answer',progress.answer,'correct',passed));
 if jsonb_array_length(hist)>100 then hist=hist-0;end if;
 update pn_private.group_board_progress set checked=true,feedback=jsonb_build_object('status',case when passed then 'correct' else 'try_again' end),revision=revision+1,attempt_history=hist where assignment_id=a.id;
 elsif action in ('next','finish') then
 if not progress.checked and not (p_input->>'skip')::boolean then return '{"error":"INVALID_INPUT"}';end if;
 if action='finish' then
 if progress.position<>jsonb_array_length(d->'items')-1 then return '{"error":"INVALID_INPUT"}';end if;
 update public.group_assignments set status='completed',revision=revision+1 where id=a.id returning * into a;
 update pn_private.group_board_progress set revision=revision+1 where assignment_id=a.id;
 else
 if progress.position>=jsonb_array_length(d->'items')-1 then return '{"error":"INVALID_INPUT"}';end if;
 update pn_private.group_board_progress set position=position+1,revision=revision+1,answer=null,checked=false,feedback=null where assignment_id=a.id;
 update public.library_runs set position=position+1,revision=revision+1 where id=r.id;
 end if;
 else return '{"error":"INVALID_INPUT"}';end if;
 insert into pn_private.group_board_receipts values(a.id,u,(p_input->>'requestId')::uuid,p_input);return pn_private.group_board_dto(a);
exception when invalid_text_representation then return '{"error":"INVALID_INPUT"}';end $$;
revoke all on function public.group_board_action(jsonb,uuid) from public,anon;grant execute on function public.group_board_action(jsonb,uuid) to authenticated;
create or replace function pn_private.presentation_session_open(p_session uuid) returns boolean language sql stable set search_path='' as $$
 select not exists(select 1 from public.library_runs r where r.id=p_session and (r.status='closed' or r.prepared or (r.parent_lesson_id is not null and not exists(select 1 from public.group_assignments a join public.group_lessons l on l.id=a.lesson_id where a.run_id=r.id and a.method='board' and a.status in ('active','completed') and l.status='active'))))
 and not exists(select 1 from pn_private.sync_sessions s where s.id=p_session and (s.deleted or s.payload#>>'{cycle,classEnded}'='true'))
$$;

create function public.learning_results(p_input jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare r public.library_runs;l public.group_lessons;d jsonb;entries jsonb;more boolean;offset_n int=0;
begin
 if auth.uid() is null or coalesce(auth.jwt()->>'is_anonymous','')<>'false' then return '{"error":"FORBIDDEN"}';end if;
 if not pn_private.matches_sync_schema((select body from pn_private.sync_schemas where id='results-v1'),p_input) then return '{"error":"INVALID_INPUT"}';end if;
 if p_input->>'action'='detail' then
 if p_input->>'source'='library' then select * into r from public.library_runs where id=(p_input->>'id')::uuid and owner_id=auth.uid();if not found then return '{"error":"NOT_FOUND"}';end if;return jsonb_build_object('source','library','detail',pn_private.learning_detail(r));
 elsif p_input->>'source'='group_lesson' then select * into l from public.group_lessons where id=(p_input->>'id')::uuid and owner_id=auth.uid();if not found then return '{"error":"NOT_FOUND"}';end if;return jsonb_build_object('source','group_lesson','lesson',pn_private.lesson_dto(l),'runs',coalesce((select jsonb_agg(pn_private.learning_detail(rr) order by rr.id) from public.library_runs rr join public.group_assignments a on a.run_id=rr.id where a.lesson_id=l.id),'[]'));
 else select payload into d from pn_private.sync_sessions where id=(p_input->>'id')::uuid and owner_id=auth.uid() and not deleted;if not found then return '{"error":"NOT_FOUND"}';end if;return jsonb_build_object('source','diagnostic','detail',d);end if;
 end if;
 if p_input?'cursor' then if p_input->>'cursor' !~ '^[0-9]{1,8}$' then return '{"error":"INVALID_INPUT"}';end if;offset_n=(p_input->>'cursor')::int;end if;
 with all_entries as (
 select rr.lesson_date date,rr.id,'library:'||rr.id::text key,rr.class_id,rr.class_label,v.document->>'title' title,rr.status,case when coalesce(rr.response_method,case when rr.mode='assessment' then 'cards' else 'none' end)='cards' then 'cards' else 'activity' end template,'library' source,rr.synthetic from public.library_runs rr join public.question_versions v on v.set_id=rr.set_id and v.version=rr.version where rr.owner_id=auth.uid() and rr.parent_lesson_id is null
 union all select ll.lesson_date,ll.id,'group_lesson:'||ll.id::text,ll.class_id,ll.payload->>'classLabel','Belajar kelompok',case when ll.status='closed' then 'closed' else 'active' end,'groups','group_lesson',(ll.payload->>'synthetic')::boolean from public.group_lessons ll where ll.owner_id=auth.uid() and ll.status<>'draft'
 union all select null::date,s.id,'diagnostic:'||s.id::text,s.class_id,c.label,'Cek kemampuan',case when s.payload#>>'{cycle,classEnded}'='true' then 'closed' else 'active' end,'diagnostic','diagnostic',c.runtime_mode='demo' from pn_private.sync_sessions s join public.classes c on c.id=s.class_id where s.owner_id=auth.uid() and not s.deleted),
 page as(select * from all_entries where (not p_input?'classId' or class_id=(p_input->>'classId')::uuid) and (not p_input?'from' or date>=(p_input->>'from')::date) and (not p_input?'to' or date<=(p_input->>'to')::date) order by date desc nulls last,key limit 51 offset offset_n),
 numbered as(select *,row_number() over(order by date desc nulls last,key) n from page)
 select coalesce(jsonb_agg(jsonb_build_object('key',key,'source',source,'id',id,'classId',class_id,'classLabel',class_label,'date',coalesce(date::text,''),'title',title,'status',status,'template',template,'synthetic',synthetic) order by n) filter(where n<=50),'[]'),count(*)>50 into entries,more from numbered;
 return jsonb_build_object('entries',entries,'nextCursor',case when more then (offset_n+50)::text else null end);
exception when invalid_text_representation or datetime_field_overflow then return '{"error":"INVALID_INPUT"}';end $$;
revoke all on function public.learning_results(jsonb) from public,anon;grant execute on function public.learning_results(jsonb) to authenticated;
