revoke all on function pn_private.valid_competency(jsonb),pn_private.valid_mapping(jsonb,jsonb),pn_private.learning_run_dto(public.library_runs),pn_private.learning_set_dto(public.question_sets),pn_private.learning_detail(public.library_runs),pn_private.record_learning_response(),pn_private.lesson_dto(public.group_lessons),pn_private.topic_evidence(uuid,jsonb,jsonb),pn_private.suggest_groups(jsonb,jsonb,integer,text,text),pn_private.valid_lesson_groups(jsonb,jsonb),pn_private.rational_value(jsonb),pn_private.tool_matches(jsonb,jsonb),pn_private.group_board_dto(public.group_assignments) from public,anon,authenticated;

