revoke all on function public.library_board_before_learning(uuid) from public,anon,authenticated;
create function public.library_board(p_presentation uuid) returns jsonb language plpgsql security definer set search_path='' as $$
begin
 if not exists(select 1 from pn_private.presentations p where p.id=p_presentation and p.board_id=auth.uid() and not p.revoked and p.expires_at>now() and pn_private.presentation_session_open(p.session_id)) then return 'null';end if;
 return public.library_board_before_learning(p_presentation);
end $$;
revoke all on function public.library_board(uuid) from public,anon;grant execute on function public.library_board(uuid) to authenticated;

revoke all on function pn_private.rational_equal(jsonb,jsonb),pn_private.rational_operate(jsonb,jsonb,text) from public,anon,authenticated;
create function pn_private.valid_group_payload(payload jsonb) returns boolean language sql stable set search_path='' as $$select pn_private.matches_sync_schema((select body from pn_private.sync_schemas where id='group-lesson-v1'),payload)$$;
revoke all on function pn_private.valid_group_payload(jsonb) from public,anon,authenticated;
alter table public.group_lessons add constraint group_payload_schema check(pn_private.valid_group_payload(payload));
commit;




